51	/**
52	 * Separated network server for server2server container replication.
53	 */
54	public class ReplicationServer {
55	
56	  private static final Logger LOG =
57	      LoggerFactory.getLogger(ReplicationServer.class);
58	
59	  private Server server;
60	
61	  private SecurityConfig secConf;
62	
63	  private CertificateClient caClient;
64	
65	  private ContainerController controller;
66	
67	  private int port;
68	  private final ContainerImporter importer;
69	
70	  private ThreadPoolExecutor executor;
71	
72	  public ReplicationServer(ContainerController controller,
73	      ReplicationConfig replicationConfig, SecurityConfig secConf,
74	      CertificateClient caClient, ContainerImporter importer,
75	      String threadNamePrefix) {
76	    this.secConf = secConf;
77	    this.caClient = caClient;
78	    this.controller = controller;
79	    this.importer = importer;
80	    this.port = replicationConfig.getPort();
81	
82	    int replicationServerWorkers =
83	        replicationConfig.getReplicationMaxStreams();
84	    int replicationQueueLimit =
85	        replicationConfig.getReplicationQueueLimit();
86	    LOG.info("Initializing replication server with thread count = {}"
87	            + " queue length = {}",
88	        replicationConfig.getReplicationMaxStreams(),
89	        replicationConfig.getReplicationQueueLimit());
90	    ThreadFactory threadFactory = new ThreadFactoryBuilder()
91	        .setDaemon(true)
92	        .setNameFormat(threadNamePrefix + "ReplicationContainerReader-%d")
93	        .build();
94	    this.executor = new ThreadPoolExecutor(
95	        replicationServerWorkers,
96	        replicationServerWorkers,
97	        60,
98	        TimeUnit.SECONDS,
99	        new LinkedBlockingQueue<>(replicationQueueLimit),
100	        threadFactory);
101	
102	    init(replicationConfig.isZeroCopyEnable());
103	  }
104	
105	  public void init(boolean enableZeroCopy) {
106	    GrpcReplicationService grpcReplicationService = new GrpcReplicationService(
107	        new OnDemandContainerReplicationSource(controller), importer,
108	        enableZeroCopy);
109	    NettyServerBuilder nettyServerBuilder = NettyServerBuilder.forPort(port)
110	        .maxInboundMessageSize(OzoneConsts.OZONE_SCM_CHUNK_MAX_SIZE)
111	        .addService(ServerInterceptors.intercept(
112	            grpcReplicationService.bindServiceWithZeroCopy(),
113	            new GrpcServerInterceptor()))
114	        .executor(executor);
115	
116	    if (secConf.isSecurityEnabled() && secConf.isGrpcTlsEnabled()) {
117	      try {
118	        SslContextBuilder sslContextBuilder = SslContextBuilder.forServer(caClient.getKeyManager());
119	
120	        sslContextBuilder = GrpcSslContexts.configure(
121	            sslContextBuilder, secConf.getGrpcSslProvider());
122	
123	        sslContextBuilder.clientAuth(ClientAuth.REQUIRE);
124	        sslContextBuilder.trustManager(caClient.getTrustManager());
125	
126	        nettyServerBuilder.sslContext(sslContextBuilder.build());
127	      } catch (IOException ex) {
128	        throw new IllegalArgumentException(
129	            "Unable to setup TLS for secure datanode replication GRPC "
130	                + "endpoint.", ex);
131	      }
132	    }
133	
134	    server = nettyServerBuilder.build();
135	  }
136	
137	  public void start() throws IOException {
138	    server.start();
139	    port = server.getPort();
140	    LOG.info("{} is started using port {}", getClass().getSimpleName(), port);
141	  }
142	
143	  public void stop() {
144	    try {
145	      executor.shutdown();
146	      executor.awaitTermination(5L, TimeUnit.SECONDS);
147	      server.shutdown().awaitTermination(10L, TimeUnit.SECONDS);
148	    } catch (InterruptedException ex) {
149	      LOG.warn("{} couldn't be stopped gracefully", getClass().getSimpleName());
150	      Thread.currentThread().interrupt();
151	    }
152	  }
153	
154	  public int getPort() {
155	    return port;
156	  }
157	
158	  public void setPoolSize(int size) {
159	    if (size <= 0) {
160	      throw new IllegalArgumentException("Pool size must be positive.");
161	    }
162	
163	    int currentCorePoolSize = executor.getCorePoolSize();
164	
165	    // In ThreadPoolExecutor, maximumPoolSize must always be greater than or
166	    // equal to the corePoolSize. We must make sure this invariant holds when
167	    // changing the pool size. Therefore, we take into account whether the
168	    // new size is greater or smaller than the current core pool size.
169	    if (size > currentCorePoolSize) {
170	      executor.setMaximumPoolSize(size);
171	      executor.setCorePoolSize(size);
172	    } else {
173	      executor.setCorePoolSize(size);
174	      executor.setMaximumPoolSize(size);
175	    }
176	  }
