29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	
32	import java.io.IOException;
33	import java.io.InputStream;
34	import java.io.OutputStream;
35	import java.nio.file.Files;
36	import java.nio.file.Path;
37	
38	import static org.apache.ratis.util.Preconditions.assertSame;
39	
40	/**
41	 * Handles incoming container pushed by other datanode.
42	 */
43	class SendContainerRequestHandler
44	    implements StreamObserver<SendContainerRequest> {
45	
46	  private static final Logger LOG =
47	      LoggerFactory.getLogger(SendContainerRequestHandler.class);
48	
49	  private final ContainerImporter importer;
50	  private final StreamObserver<SendContainerResponse> responseObserver;
51	
52	  private long containerId = -1;
53	  private long nextOffset;
54	  private OutputStream output;
55	  private HddsVolume volume;
56	  private Path path;
57	  private CopyContainerCompression compression;
58	  private final ZeroCopyMessageMarshaller<SendContainerRequest> marshaller;
59	
60	  SendContainerRequestHandler(
61	      ContainerImporter importer,
62	      StreamObserver<SendContainerResponse> responseObserver,
63	      ZeroCopyMessageMarshaller<SendContainerRequest> marshaller) {
64	    this.importer = importer;
65	    this.responseObserver = responseObserver;
66	    this.marshaller = marshaller;
67	  }
68	
69	  @Override
70	  public void onNext(SendContainerRequest req) {
71	    try {
72	      final long length = req.getData().size();
73	      LOG.debug("Received part for container id:{} offset:{} len:{}",
74	          req.getContainerID(), req.getOffset(), length);
75	
76	      assertSame(nextOffset, req.getOffset(), "offset");
77	
78	      // check and avoid download of container file if target already have
79	      // container data and import in progress
80	      if (!importer.isAllowedContainerImport(req.getContainerID())) {
81	        containerId = req.getContainerID();
82	        throw new StorageContainerException("Container exists or " +
83	            "import in progress with container Id " + req.getContainerID(),
84	            ContainerProtos.Result.CONTAINER_EXISTS);
85	      }
86	
87	      if (containerId == -1) {
88	        containerId = req.getContainerID();
89	        volume = importer.chooseNextVolume();
90	        Path dir = ContainerImporter.getUntarDirectory(volume);
91	        Files.createDirectories(dir);
92	        path = dir.resolve(ContainerUtils.getContainerTarName(containerId));
93	        output = Files.newOutputStream(path);
94	        compression = CopyContainerCompression.fromProto(req.getCompression());
95	
96	        LOG.info("Accepting container {}", req.getContainerID());
97	      }
98	
99	      assertSame(containerId, req.getContainerID(), "containerID");
100	
101	      req.getData().writeTo(output);
102	
103	      nextOffset += length;
104	    } catch (Throwable t) {
105	      onError(t);
106	    } finally {
107	      if (marshaller != null) {
108	        InputStream popStream = marshaller.popStream(req);
109	        if (popStream != null) {
110	          IOUtils.cleanupWithLogger(LOG, popStream);
111	        }
112	      }
113	    }
114	  }
115	
116	  @Override
117	  public void onError(Throwable t) {
118	    LOG.warn("Error receiving container {} at {}", containerId, nextOffset, t);
119	    closeOutput();
120	    deleteTarball();
121	    responseObserver.onError(t);
122	  }
123	
124	  @Override
125	  public void onCompleted() {
126	    if (output == null) {
127	      LOG.warn("Received container without any parts");
128	      return;
129	    }
130	
131	    LOG.info("Container {} is downloaded with size {}, starting to import.",
132	        containerId, nextOffset);
133	    closeOutput();
134	
135	    try {
136	      importer.importContainer(containerId, path, volume, compression);
137	      LOG.info("Container {} is replicated successfully", containerId);
138	      responseObserver.onNext(SendContainerResponse.newBuilder().build());
139	      responseObserver.onCompleted();
140	    } catch (Throwable t) {
141	      LOG.warn("Failed to import container {}", containerId, t);
142	      deleteTarball();
143	      responseObserver.onError(t);
144	    }
145	  }
146	
147	  private void closeOutput() {
148	    IOUtils.close(LOG, output);
149	    output = null;
150	  }
151	
152	  private void deleteTarball() {
153	    try {
154	      if (null != path) {
155	        Files.deleteIfExists(path);
156	      }
157	    } catch (IOException e) {
158	      LOG.warn("Error removing {}", path);
159	    }
160	  }
161	}
